// @FIGURE_CODE_BEGIN
/* ── colours (matched to the source figure) ─────────────────────────────── */
var COL = {
  curve: '#1f4e79',
  vertexTxt: '#17365d',
  sym: '#e8632a',
  focus: '#159c8c',
  latus: '#6fa8dc',
  latusTxt: '#3f7fc4',
  dir: '#e03127',
  segF: '#0f8f84',
  segD: '#e03127'
};

/* ── geometry constants (world units) ───────────────────────────────────── */
var VX = 1.0;          // vertex x  (axis of symmetry sits right of the y-axis)
var VY = 1.3;          // vertex y  (vertex sits above the x-axis)
