    var gC = figDraw.group();
    var tLimY = Math.sqrt(Math.max(0.01, 4 * p * (yD[1] - 0.45 - k)));
    var tLimR = xD[1] - 0.75 - h, tLimL = h - (xD[0] + 0.35);
    var t = figState.t;
    t = Math.max(-Math.min(tLimY, tLimL), Math.min(Math.min(tLimY, tLimR), t));
    var pxw = h + t, pyw = k + t * t / (4 * p);
    var Px = plotX(pxw), Py = plotY(pyw);
    var Fx = fXs, Fy = fYs, Dx = Px, Dy = dYs;
    var dist = pyw - dy;

    /* segments */
    gC.line(Px, Py, Fx, Fy).stroke({ color: COL.segF, width: Math.max(1.4, 2.6 * K), linecap: 'round' });
    gC.line(Px, Py, Dx, Dy).stroke({ color: COL.segD, width: Math.max(1.4, 2.6 * K), linecap: 'round' });

    /* right-angle marker at the foot on the directrix */
    var sq = 9 * K, sgn = (Fx >= Dx) ? 1 : -1;
    gC.polyline([[Dx + sgn * sq, Dy], [Dx + sgn * sq, Dy - sq], [Dx, Dy - sq]]
      .map(function (q) { return q[0] + ',' + q[1]; }).join(' '))
      .fill('none').stroke({ color: COL.segD, width: Math.max(0.8, 1.3 * K) });
    gC.circle(4 * K).center(Dx, Dy).fill(COL.segD);

    /* equal tick marks on both segments */
    equalTicks(gC, Px, Py, Fx, Fy, COL.segF, 2, K);
    equalTicks(gC, Px, Py, Dx, Dy, COL.segD, 2, K);

    /* length labels */
    var mfx = (Px + Fx) / 2, mfy = (Py + Fy) / 2;
    var ddx = Fx - Px, ddy = Fy - Py, LL = Math.sqrt(ddx * ddx + ddy * ddy) || 1;
    var nx = -ddy / LL, ny = ddx / LL;
    var c1 = [mfx + nx * 16 * K, mfy + ny * 16 * K], c2 = [mfx - nx * 16 * K, mfy - ny * 16 * K];
    var d1 = Math.hypot(c1[0] - vXs, c1[1] - vYs), d2 = Math.hypot(c2[0] - vXs, c2[1] - vYs);
    var cc = (d1 >= d2) ? c1 : c2;
    txt(gC, cc[0], cc[1] + 4 * K, 'PF = ' + dist.toFixed(2),
        { fill: COL.segF, size: FS * 0.92, anchor: 'middle', weight: 'bold' });

    var sideD = (pxw >= h) ? 1 : -1;
    txt(gC, Dx + sideD * 11 * K, (Py + Dy) / 2 + 4 * K, 'PD = ' + dist.toFixed(2),
        { fill: COL.segD, size: FS * 0.92, anchor: (sideD > 0 ? 'start' : 'end'), weight: 'bold' });

    /* p brackets between vertex↔focus and vertex↔directrix */
    var bside = (pxw >= h) ? -1 : 1;
    var bx = vXs + bside * 15 * K, cap = 4 * K;
    var bcol = '#555';
    [[vYs, fYs], [vYs, dYs]].forEach(function (pair) {
      gC.line(bx, pair[0], bx, pair[1]).stroke({ color: bcol, width: Math.max(0.7, 1.1 * K) });
      gC.line(bx - cap, pair[0], bx + cap, pair[0]).stroke({ color: bcol, width: Math.max(0.7, 1.1 * K) });
      gC.line(bx - cap, pair[1], bx + cap, pair[1]).stroke({ color: bcol, width: Math.max(0.7, 1.1 * K) });
      txt(gC, bx + bside * 6 * K, (pair[0] + pair[1]) / 2 + 4 * K, 'p',
          { fill: '#333', size: FS * 0.95, style: 'italic', anchor: (bside > 0 ? 'start' : 'end') });
    });

    /* the movable point P */
    gC.circle(15 * K).center(Px, Py).fill(COL.sym).opacity(0.28);
    gC.circle(8.5 * K).center(Px, Py).fill(COL.curve).stroke({ color: '#fff', width: Math.max(0.8, 1.6 * K) });
    var pl = (pxw >= h) ? 1 : -1;
    txt(gC, Px + pl * 11 * K, Py - 9 * K, 'P',
        { fill: COL.curve, size: FS * 1.05, weight: 'bold', anchor: (pl > 0 ? 'start' : 'end') });

    gC.css('cursor', 'pointer');
    gC.on('mousemove', function (e) {
      showTooltip('PF = PD = ' + dist.toFixed(2) + '  (both equal p = ' + p.toFixed(1) + ' at the vertex)', e);
    });
    gC.on('mouseleave', hideTooltip);
    gC.on('click', function () {
      showPopup('Equal distances',
        'The teal segment runs from P to the focus; the red segment drops perpendicular from P to the directrix. They measure ' +
        dist.toFixed(2) + ' each — and they stay equal for every position of P. At the vertex both shrink to p, which is why the vertex sits exactly halfway between focus and directrix.');
    });
  }

  applyHover();
}

/* ── interaction handlers ───────────────────────────────────────────────── */
function update_focalDistance(v) { figState.p = v; render(); }
function update_samplePoint(v) { figState.t = v; render(); }
function toggle_viewMode(on) { figState.construct = !!on; render(); }

/* ── demo steps ─────────────────────────────────────────────────────────── */
var DEMO = [
  { title: '1 · The named parts',
    narration: 'The standard labeled parabola: dark-blue curve, its vertex, the teal focus above it, the red directrix below, the orange axis of symmetry through both, and the dashed latus rectum across the focus. Hover any feature to light it up alone.',
    state: { viewMode: 'Labeled features', focalDistance: 1 } },
  { title: '2 · Why equidistant?',
    narration: 'Switch to the distance construction. A point P on the curve grows a teal segment to the focus and a red perpendicular segment down to the directrix — and they are exactly the same length.',
    state: { viewMode: 'Distance construction', focalDistance: 1, samplePoint: 1.6 } },
  { title: '3 · It holds everywhere',
    narration: 'Slide P along the curve. The two segments change length together but never differ — this equality is the definition of the parabola, not a special case.',
    state: { viewMode: 'Distance construction', focalDistance: 1, samplePoint: -2.4 } },
  { title: '4 · The vertex is the midpoint',
    narration: 'Move P to the bottom. Both distances shrink to the same value p: the vertex is the one point sitting halfway between focus and directrix, on the axis of symmetry.',
    state: { viewMode: 'Distance construction', focalDistance: 1, samplePoint: 0 } },
  { title: '5 · Changing p reshapes the curve',
    narration: 'Increase p: the focus climbs, the directrix drops the same amount, and the parabola opens out wide with a latus rectum of width 4p.',
    state: { viewMode: 'Distance construction', focalDistance: 2.5, samplePoint: 1.6 } },
  { title: '6 · A tight parabola',
    narration: 'Shrink p and the focus and directrix squeeze toward the vertex, pinching the curve into a narrow channel — same definition, different single parameter.',
    state: { viewMode: 'Labeled features', focalDistance: 0.4, samplePoint: 1.6 } }
];

function setSliderVal(id, v) {
  var inp = document.getElementById(id + 'Input');
  var out = document.getElementById(id + 'Val');
  if (inp) inp.value = v;
  if (out) out.value = v;
}

function applyStep(i) {
  figState.step = ((i % DEMO.length) + DEMO.length) % DEMO.length;
  var s = DEMO[figState.step], st = s.state || {};
  if (st.focalDistance != null) { setSliderVal('focalDistance', st.focalDistance); figState.p = st.focalDistance; }
  if (st.samplePoint != null) { setSliderVal('samplePoint', st.samplePoint); figState.t = st.samplePoint; }
  if (st.viewMode != null) {
    var on = (st.viewMode === 'Distance construction');
    var cb = document.getElementById('viewModeInput');
    if (cb) cb.checked = on;
    figState.construct = on;
  }
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (figState.step + 1) + ' / ' + DEMO.length;
  render();
}
function nextStep() { applyStep(figState.step + 1); }
function prevStep() { applyStep(figState.step - 1); }

/* ── resize + boot ──────────────────────────────────────────────────────── */
document.addEventListener('fig-resize', function () { render(); });

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A parabola is the set of all points equidistant from a fixed point (the focus) and a fixed line (the directrix), with the vertex, axis of symmetry, and latus rectum naming the key parts of that construction.
KEY INSIGHT (what students should walk away understanding): Every point on a parabola is the same distance from the focus as from the directrix — the vertex is simply the point where that shared distance is smallest, which is why it sits exactly halfway between them.
DEMO STEPS: 6 guided steps — implement the step player in #ui

