// @FIGURE_CODE_BEGIN
/* ── colours (matched to the source figure) ─────────────────────────────── */
var COL = {
  curve: '#1f4e79',
  vertexTxt: '#17365d',
  sym: '#e8632a',
  focus: '#159c8c',
  latus: '#6fa8dc',
  latusTxt: '#3f7fc4',
  dir: '#e03127',
  segF: '#0f8f84',
  segD: '#e03127'
};

/* ── geometry constants (world units) ───────────────────────────────────── */
var VX = 1.0;          // vertex x  (axis of symmetry sits right of the y-axis)
var VY = 1.3;          // vertex y  (vertex sits above the x-axis)

var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var figFrame = setPlotFrame({ xDomain: [-3.4, 6.2], yDomain: [-1.15, 4.7], margin: 14, draw: figDraw });

var figState = { p: 1, t: 1.6, construct: false, hover: null, step: 0 };
var figGroups = {};
var Kf = 1;

/* ── composition: equal x/y scale, extra space weighted like the original ── */
function fixAspect() {
  var p = figState.p;
  var fy = VY + p, dy = VY - p;
  var cx0 = -3.4, cx1 = 6.2;
  var cy0 = Math.min(-1.15, dy - 0.45);
  var cy1 = Math.max(4.7, fy + 1.25);
  var m = figFrame.margin;
  var aw = Math.max(40, figFrame.width - 2 * m);
  var ah = Math.max(40, figFrame.height - 2 * m);
  var cw = cx1 - cx0, ch = cy1 - cy0;
  var s = Math.min(aw / cw, ah / ch);
  figFrame.sx = s; figFrame.sy = s;
  var wx = aw / s, wy = ah / s;
  var ex = Math.max(0, wx - cw), ey = Math.max(0, wy - ch);
  figFrame.xDomain = [cx0 - ex * 0.45, cx1 + ex * 0.55];
  figFrame.yDomain = [cy0 - ey * 0.20, cy1 + ey * 0.80];
}

/* ── small helpers ──────────────────────────────────────────────────────── */
function txt(g, x, y, str, o) {
  o = o || {};
  var t = g.plain(String(str));
  t.attr({
    x: x, y: y,
    'text-anchor': o.anchor || 'start',
    'font-family': 'sans-serif',
    'font-size': (o.size || 13 * Kf),
    'font-weight': o.weight || 'normal',
    'font-style': o.style || 'normal',
    fill: o.fill || '#000'
  });
  if (o.halo !== false) {
    t.attr({
      'paint-order': 'stroke', stroke: '#ffffff',
      'stroke-width': (o.haloW == null ? Math.max(1.6, 3.4 * Kf) : o.haloW),
      'stroke-linejoin': 'round'
    });
  }
  return t;
}

function textW(str, size) { return String(str).length * size * 0.56; }

function arrowHead(g, x, y, ang, color, size) {
  var a = size, b = size * 0.52;
  var ca = Math.cos(ang), sa = Math.sin(ang);
  var p1 = [x, y];
  var p2 = [x - a * ca + b * sa, y - a * sa - b * ca];
  var p3 = [x - a * ca - b * sa, y - a * sa + b * ca];
  return g.polygon([p1, p2, p3].map(function (q) { return q[0] + ',' + q[1]; }).join(' ')).fill(color);
}

function hitLine(g, x1, y1, x2, y2, w) {
  g.line(x1, y1, x2, y2).stroke({ color: '#000', width: w, opacity: 0 }).attr('pointer-events', 'stroke');
}

function attachFeature(g, key, tip, title, body) {
  g.css('cursor', 'pointer');
  g.on('mousemove', function (e) { showTooltip(tip, e); });
  g.on('mouseenter', function () { figState.hover = key; applyHover(); });
  g.on('mouseleave', function () { hideTooltip(); figState.hover = null; applyHover(); });
  g.on('click', function () { showPopup(title, body); });
}

function applyHover() {
  Object.keys(figGroups).forEach(function (k) {
    var op = (!figState.hover || figState.hover === k) ? 1 : 0.15;
    figGroups[k].opacity(op);
  });
}

function equalTicks(g, x1, y1, x2, y2, color, n, K) {
  var mx = (x1 + x2) / 2, my = (y1 + y2) / 2;
  var dx = x2 - x1, dy = y2 - y1, L = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / L, uy = dy / L, nx = -uy, ny = ux;
  var len = 5.2 * K, gap = 4 * K;
  for (var i = 0; i < n; i++) {
    var off = (i - (n - 1) / 2) * gap;
    g.line(mx + ux * off - nx * len, my + uy * off - ny * len,
           mx + ux * off + nx * len, my + uy * off + ny * len)
      .stroke({ color: color, width: Math.max(0.9, 1.6 * K) });
  }
}

/* ── main render ────────────────────────────────────────────────────────── */
function render() {
  fixAspect();
  Kf = Math.max(0.5, Math.min(2.1, figFrame.sx / 52));
  var K = Kf;
  var FS = 13.5 * K;
  figDraw.clear();
  figGroups = {};

  var xD = figFrame.xDomain, yD = figFrame.yDomain;
  var h = VX, k = VY, p = figState.p;
  var fy = k + p, dy = k - p;
  var dim = figState.construct ? 0.3 : 1;

  /* ---------- axes ---------- */
  var gAx = figDraw.group();
  var axL = xD[0] + 0.30, axR = xD[1] - 0.70, ayB = yD[0] + 0.22, ayT = yD[1] - 0.16;
  var axW = Math.max(0.8, 1.3 * K);
  gAx.line(plotX(axL), plotY(0), plotX(axR), plotY(0)).stroke({ color: '#000', width: axW });
  gAx.line(plotX(0), plotY(ayB), plotX(0), plotY(ayT)).stroke({ color: '#000', width: axW });
  var ah = 7.5 * K;
  arrowHead(gAx, plotX(axR), plotY(0), 0, '#000', ah);
  arrowHead(gAx, plotX(axL), plotY(0), Math.PI, '#000', ah);
  arrowHead(gAx, plotX(0), plotY(ayT), -Math.PI / 2, '#000', ah);
  arrowHead(gAx, plotX(0), plotY(ayB), Math.PI / 2, '#000', ah);
  txt(gAx, plotX(axR) + 7 * K, plotY(0) + 17 * K, 'x',
      { fill: '#000', size: FS * 1.15, weight: 'bold', style: 'italic' });
  txt(gAx, plotX(0) + 9 * K, plotY(ayT) + 12 * K, 'y',
      { fill: '#000', size: FS * 1.15, weight: 'bold', style: 'italic' });

  /* ---------- directrix ---------- */
  var gDir = figDraw.group(); figGroups.directrix = gDir;
  var dLx = plotX(xD[0] + 0.14), dRx = plotX(xD[1] - 0.22), dYs = plotY(dy);
  gDir.line(dLx, dYs, dRx, dYs)
    .stroke({ color: COL.dir, width: Math.max(1.2, 2.1 * K), dasharray: (7 * K) + ',' + (5 * K) });
  hitLine(gDir, dLx, dYs, dRx, dYs, 15 * K);
  txt(gDir, dRx - 6 * K, dYs - 9 * K, 'Directrix',
      { fill: COL.dir, size: FS, anchor: 'end' }).opacity(dim);
  attachFeature(gDir, 'directrix', 'Directrix — the fixed line; every curve point is as far from it as from the focus',
    'Directrix',
    'The directrix is the fixed line in the definition of a parabola. It is perpendicular to the axis of symmetry and sits a distance p below the vertex, mirroring the focus which sits a distance p above. Distance from a point to the directrix is measured perpendicular to the line.');

