// @FIGURE_CODE_BEGIN
/* ── colours (matched to the source figure) ─────────────────────────────── */
var COL = {
  curve: '#1f4e79',
  vertexTxt: '#17365d',
  sym: '#e8632a',
  focus: '#159c8c',
  latus: '#6fa8dc',
  latusTxt: '#3f7fc4',
  dir: '#e03127',
  segF: '#0f8f84',
  segD: '#e03127'
};

/* ── fixed world anchors (vertex sits right of the y-axis, above the x-axis) */
var VX = 2.6;
var VY = 1.6;

var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var figFrame = setPlotFrame({ xDomain: [-3, 9], yDomain: [-2.4, 8], margin: 14, draw: figDraw });

var figState = { p: 1, t: 1.6, construct: false, hover: null, step: 0 };
var figGroups = {};
var Kf = 1;

/* ── composition ────────────────────────────────────────────────────────────
   The drawn curve keeps a roughly constant rise, so its half-width grows only
   as sqrt(p): a narrow bowl with generous whitespace at the default p = 1.   */
function computeLayout() {
  var p = figState.p;
  var wHalf = Math.min(4.67 * Math.sqrt(p), 7.2);
  var rise = wHalf * wHalf / (4 * p);
  var fy = VY + p, dy = VY - p;
  var cx0 = VX - wHalf - 1.0, cx1 = VX + wHalf + 1.9;
  var cy0 = Math.min(-2.4, dy - 1.0);
  var cy1 = VY + rise + 1.05;

  var m = figFrame.margin;
  var aw = Math.max(40, figFrame.width - 2 * m);
  var ah = Math.max(40, figFrame.height - 2 * m);
  var cw = cx1 - cx0, ch = cy1 - cy0;
  var s = Math.min(aw / cw, ah / ch);
  figFrame.sx = s; figFrame.sy = s;
  var ex = Math.max(0, aw / s - cw), ey = Math.max(0, ah / s - ch);
  figFrame.xDomain = [cx0 - ex * 0.5, cx1 + ex * 0.5];
  figFrame.yDomain = [cy0 - ey * 0.40, cy1 + ey * 0.60];

  return { p: p, wHalf: wHalf, rise: rise, fy: fy, dy: dy, cx0: cx0, cx1: cx1, cy0: cy0, cy1: cy1 };
}

/* ── small helpers ──────────────────────────────────────────────────────── */
function txt(g, x, y, str, o) {
  o = o || {};
  var t = g.plain(String(str));
  t.attr({
    x: x, y: y,
    'text-anchor': o.anchor || 'start',
    'font-family': 'sans-serif',
    'font-size': (o.size || 13 * Kf),
    'font-weight': o.weight || 'normal',
    'font-style': o.style || 'normal',
    fill: o.fill || '#000'
  });
  if (o.halo !== false) {
    t.attr({
      'paint-order': 'stroke', stroke: '#ffffff',
      'stroke-width': (o.haloW == null ? Math.max(1.6, 3.4 * Kf) : o.haloW),
      'stroke-linejoin': 'round'
    });
  }
  return t;
}

function textW(str, size) { return String(str).length * size * 0.56; }

function arrowHead(g, x, y, ang, color, size) {
  var a = size, b = size * 0.52;
  var ca = Math.cos(ang), sa = Math.sin(ang);
  var p1 = [x, y];
  var p2 = [x - a * ca + b * sa, y - a * sa - b * ca];
  var p3 = [x - a * ca - b * sa, y - a * sa + b * ca];
  return g.polygon([p1, p2, p3].map(function (q) { return q[0] + ',' + q[1]; }).join(' ')).fill(color);
}

function hitLine(g, x1, y1, x2, y2, w) {
  g.line(x1, y1, x2, y2).stroke({ color: '#000', width: w, opacity: 0 }).attr('pointer-events', 'stroke');
}

function attachFeature(g, key, tip, title, body) {
  g.css('cursor', 'pointer');
  g.on('mousemove', function (e) { showTooltip(tip, e); });
  g.on('mouseenter', function () { figState.hover = key; applyHover(); });
  g.on('mouseleave', function () { hideTooltip(); figState.hover = null; applyHover(); });
  g.on('click', function () { showPopup(title, body); });
}

function applyHover() {
  Object.keys(figGroups).forEach(function (k) {
    var op = (!figState.hover || figState.hover === k) ? 1 : 0.15;
    figGroups[k].opacity(op);
  });
}

function equalTicks(g, x1, y1, x2, y2, color, n, K) {
  var mx = (x1 + x2) / 2, my = (y1 + y2) / 2;
  var dx = x2 - x1, dy = y2 - y1, L = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / L, uy = dy / L, nx = -uy, ny = ux;
  var len = 5.2 * K, gap = 4 * K;
  for (var i = 0; i < n; i++) {
    var off = (i - (n - 1) / 2) * gap;
    g.line(mx + ux * off - nx * len, my + uy * off - ny * len,
           mx + ux * off + nx * len, my + uy * off + ny * len)
      .stroke({ color: color, width: Math.max(0.9, 1.6 * K) });
  }
}

/* ── main render ────────────────────────────────────────────────────────── */
function render() {
  var L = computeLayout();
  var K = Math.max(0.62, Math.min(1.5, Math.min(figFrame.width, figFrame.height) / 500));
  Kf = K;
  var FS = 13.5 * K;
  figDraw.clear();
  figGroups = {};

  var h = VX, k = VY, p = L.p;
  var fy = L.fy, dy = L.dy;
  var dim = figState.construct ? 0.32 : 1;

  /* ---------- axes ---------- */
  var gAx = figDraw.group();
  var axL = L.cx0 + 0.10, axR = L.cx1 - 0.35, ayB = L.cy0 + 0.15, ayT = L.cy1 - 0.12;
  var axW = Math.max(0.8, 1.3 * K);
  gAx.line(plotX(axL), plotY(0), plotX(axR), plotY(0)).stroke({ color: '#000', width: axW });
  gAx.line(plotX(0), plotY(ayB), plotX(0), plotY(ayT)).stroke({ color: '#000', width: axW });
  var ah = 7.5 * K;
  arrowHead(gAx, plotX(axR), plotY(0), 0, '#000', ah);
  arrowHead(gAx, plotX(axL), plotY(0), Math.PI, '#000', ah);
  arrowHead(gAx, plotX(0), plotY(ayT), -Math.PI / 2, '#000', ah);
  arrowHead(gAx, plotX(0), plotY(ayB), Math.PI / 2, '#000', ah);
  txt(gAx, plotX(axR) + 7 * K, plotY(0) + 17 * K, 'x',
      { fill: '#000', size: FS * 1.15, weight: 'bold', style: 'italic' });
  txt(gAx, plotX(0) + 9 * K, plotY(ayT) + 12 * K, 'y',
      { fill: '#000', size: FS * 1.15, weight: 'bold', style: 'italic' });

  /* ---------- directrix (short: symmetric about the axis, ends inside frame) */
  var gDir = figDraw.group(); figGroups.directrix = gDir;
  var dHalf = Math.max(3.4, 2.3 * p);
  dHalf = Math.min(dHalf, h - (L.cx0 + 0.35), (L.cx1 - 1.55) - h);
  dHalf = Math.max(dHalf, 1.2);
  var dLx = plotX(h - dHalf), dRx = plotX(h + dHalf), dYs = plotY(dy);
  gDir.line(dLx, dYs, dRx, dYs)
    .stroke({ color: COL.dir, width: Math.max(1.2, 2.1 * K), dasharray: (7 * K) + ',' + (5 * K) });
  hitLine(gDir, dLx, dYs, dRx, dYs, 15 * K);
  txt(gDir, dRx, dYs - 9 * K, 'Directrix',
      { fill: COL.dir, size: FS, anchor: 'end' }).opacity(dim);
  attachFeature(gDir, 'directrix', 'Directrix — the fixed line; every curve point is as far from it as from the focus',
    'Directrix',
    'The directrix is the fixed line in the definition of a parabola. It is perpendicular to the axis of symmetry and sits a distance p below the vertex, mirroring the focus which sits a distance p above. Distance from a point to the directrix is measured perpendicular to the line.');

  /* ---------- axis of symmetry ---------- */
  var gSym = figDraw.group(); figGroups.axis = gSym;
  var syT = plotY(L.cy1 - 0.03), syB = plotY(L.cy0 + 0.03), sxS = plotX(h);
  gSym.line(sxS, syT, sxS, syB)
    .stroke({ color: COL.sym, width: Math.max(1.2, 2.1 * K), dasharray: (7 * K) + ',' + (5 * K) });
  hitLine(gSym, sxS, syT, sxS, syB, 15 * K);
  var symTop = syT + 15 * K, symBottom = symTop + 15 * K;
  txt(gSym, sxS + 9 * K, symTop, 'Axis of', { fill: COL.sym, size: FS }).opacity(dim);
  txt(gSym, sxS + 9 * K, symBottom, 'symmetry', { fill: COL.sym, size: FS }).opacity(dim);
  attachFeature(gSym, 'axis', 'Axis of symmetry — through the focus, perpendicular to the directrix',
    'Axis of symmetry',
    'The axis of symmetry is the line through the focus that is perpendicular to the directrix. The parabola is a perfect mirror image across it, and the curve crosses it exactly at the vertex.');

  /* ---------- latus rectum (symmetric chord, endpoints on the curve) ------ */
  var gLat = figDraw.group(); figGroups.latus = gLat;
  var chordHalf = Math.min(2 * p, L.wHalf);
  var lXa = plotX(h - chordHalf), lXb = plotX(h + chordHalf), lYs = plotY(fy);
  gLat.line(lXa, lYs, lXb, lYs)
    .stroke({ color: COL.latus, width: Math.max(1.1, 1.9 * K), dasharray: (5 * K) + ',' + (4 * K) });
  hitLine(gLat, lXa, lYs, lXb, lYs, 13 * K);

  /* label lives in the open lane between the y-axis and the axis of symmetry */
  var curveTop = k + L.rise;
  var gapAbove = (curveTop - fy) * figFrame.sy;
  var gapBelow = (fy - k) * figFrame.sy;
  var above = (gapAbove >= 82 * K) || (gapAbove >= gapBelow);
  var labY = above ? (fy + (curveTop - fy) * 0.40) : (k + (fy - k) * 0.52);
  var wtxt = textW('rectum', FS);
  var lblRight = sxS - 15 * K;
  var minLeft = plotX(0) + 10 * K;
  if (lblRight - wtxt < minLeft) lblRight = Math.min(sxS - 7 * K, minLeft + wtxt);
  var ly = plotY(labY);
  txt(gLat, lblRight, ly, 'Latus', { fill: COL.latusTxt, size: FS, anchor: 'end' }).opacity(dim);
  txt(gLat, lblRight, ly + 15 * K, 'rectum', { fill: COL.latusTxt, size: FS, anchor: 'end' }).opacity(dim);

  var gArrow = gLat.group().opacity(dim);
  var sgn = above ? 1 : -1;
  var sX = lblRight - wtxt * 0.72;
  var sY = above ? (ly + 15 * K + 11 * K) : (ly - 12 * K);
  var tX = plotX(h - 0.34 * chordHalf);
  var tY = lYs - sgn * 5 * K;
  var cXc = sX + (tX - sX) * 0.18, cYc = tY - sgn * 20 * K;
  gArrow.path('M ' + sX + ' ' + sY + ' Q ' + cXc + ' ' + cYc + ' ' + tX + ' ' + tY)
    .fill('none').stroke({ color: '#000', width: Math.max(0.8, 1.2 * K) });
  arrowHead(gArrow, tX, tY, Math.atan2(tY - cYc, tX - cXc), '#000', 6.5 * K);

  attachFeature(gLat, 'latus', 'Latus rectum — chord through the focus parallel to the directrix, width 4p',
    'Latus rectum',
    'The latus rectum is the chord drawn through the focus parallel to the directrix. Its endpoints lie 2p on either side of the axis of symmetry, so it is always exactly 4p wide. Its width is a quick measure of how open the parabola is.');

  /* ---------- parabola curve ---------- */
  var gCur = figDraw.group(); figGroups.curve = gCur;
  var pts = [], N = 200, w = L.wHalf;
  for (var i = 0; i <= N; i++) {
    var xw = (h - w) + (2 * w) * i / N;
    pts.push([plotX(xw), plotY(k + (xw - h) * (xw - h) / (4 * p))]);
  }
  var ptsStr = pts.map(function (q) { return q[0] + ',' + q[1]; }).join(' ');
  gCur.polyline(ptsStr).fill('none')
    .stroke({ color: COL.curve, width: Math.max(1.6, 3.2 * K), linecap: 'round', linejoin: 'round' });
  gCur.polyline(ptsStr).fill('none')
    .stroke({ color: '#000', width: 15 * K, opacity: 0 }).attr('pointer-events', 'stroke');
  var pa = pts[pts.length - 1], pb = pts[pts.length - 2];
  arrowHead(gCur, pa[0], pa[1], Math.atan2(pa[1] - pb[1], pa[0] - pb[0]), COL.curve, 9.5 * K);
  var pc = pts[0], pd = pts[1];
  arrowHead(gCur, pc[0], pc[1], Math.atan2(pc[1] - pd[1], pc[0] - pd[0]), COL.curve, 9.5 * K);
  attachFeature(gCur, 'curve', 'Parabola — all points equidistant from the focus and the directrix',
    'The parabola',
    'Every point of this curve is exactly as far from the focus as it is from the directrix. That single rule generates the whole shape. Switch on the distance construction view and slide P to watch the two distances stay equal.');

  /* ---------- focus ---------- */
  var gFoc = figDraw.group(); figGroups.focus = gFoc;
  var fXs = sxS, fYs = lYs;
  gFoc.circle(9 * K).center(fXs, fYs).fill(COL.focus);
  gFoc.circle(20 * K).center(fXs, fYs).fill('#fff').opacity(0).attr('pointer-events', 'all');
  var focLabY = fYs - 10 * K;
  if (focLabY - 11 * K < symBottom + 6 * K) focLabY = fYs + 17 * K;
  txt(gFoc, fXs + 10 * K, focLabY, 'Focus', { fill: COL.focus, size: FS }).opacity(dim);
  attachFeature(gFoc, 'focus', 'Focus — the fixed point, a distance p above the vertex',
    'Focus',
    'The focus is the fixed point in the definition of the parabola. For every point P on the curve the straight-line distance PF equals the perpendicular distance from P down to the directrix. It sits on the axis of symmetry, a distance p above the vertex.');

  /* ---------- vertex ---------- */
  var gVer = figDraw.group(); figGroups.vertex = gVer;
  var vXs = sxS, vYs = plotY(k);
  gVer.circle(11 * K).center(vXs, vYs).fill(COL.curve);
  gVer.circle(22 * K).center(vXs, vYs).fill('#fff').opacity(0).attr('pointer-events', 'all');
  var vLabR = plotX(0) - 12 * K;
  var vMin = plotX(L.cx0) + textW('Vertex', FS) + 8 * K;
  if (vLabR < vMin) vLabR = Math.min(vXs - 46 * K, vMin);
  gVer.line(vLabR + 7 * K, vYs, vXs - 9 * K, vYs)
    .stroke({ color: '#000', width: Math.max(0.7, 1.1 * K) }).opacity(dim);
  txt(gVer, vLabR, vYs + 5 * K, 'Vertex', { fill: COL.vertexTxt, size: FS, anchor: 'end' }).opacity(dim);
  attachFeature(gVer, 'vertex', 'Vertex — halfway between focus and directrix, distance p from each',
    'Vertex',
    'The vertex is the turning point of the parabola. It lies on the axis of symmetry exactly midway between the focus and the directrix, so its distance to each of them is p. That is the smallest distance any point of the curve has to the focus.');

  /* ---------- distance construction ---------- */
  if (figState.construct) {
    var gC = figDraw.group();
    var tLim = L.wHalf * 0.93;
    var t = Math.max(-tLim, Math.min(tLim, figState.t));
    var pxw = h + t, pyw = k + t * t / (4 * p);
    var Px = plotX(pxw), Py = plotY(pyw);
    var Fx = fXs, Fy = fYs, Dx = Px, Dy = dYs;
    var dist = pyw - dy;

    gC.line(Px, Py, Fx, Fy).stroke({ color: COL.segF, width: Math.max(1.4, 2.6 * K), linecap: 'round' });
    gC.line(Px, Py, Dx, Dy).stroke({ color: COL.segD, width: Math.max(1.4, 2.6 * K), linecap: 'round' });

    var sq = 9 * K, sgn2 = (Fx >= Dx) ? 1 : -1;
    gC.polyline([[Dx + sgn2 * sq, Dy], [Dx + sgn2 * sq, Dy - sq], [Dx, Dy - sq]]
      .map(function (q) { return q[0] + ',' + q[1]; }).join(' '))
      .fill('none').stroke({ color: COL.segD, width: Math.max(0.8, 1.3 * K) });
    gC.circle(4 * K).center(Dx, Dy).fill(COL.segD);

    equalTicks(gC, Px, Py, Fx, Fy, COL.segF, 2, K);
    equalTicks(gC, Px, Py, Dx, Dy, COL.segD, 2, K);

    var mfx = (Px + Fx) / 2, mfy = (Py + Fy) / 2;
    var ddx = Fx - Px, ddy = Fy - Py, LL = Math.sqrt(ddx * ddx + ddy * ddy) || 1;
    var nx = -ddy / LL, ny = ddx / LL;
    var c1 = [mfx + nx * 18 * K, mfy + ny * 18 * K], c2 = [mfx - nx * 18 * K, mfy - ny * 18 * K];
    var d1 = Math.hypot(c1[0] - vXs, c1[1] - vYs), d2 = Math.hypot(c2[0] - vXs, c2[1] - vYs);
    var cc = (d1 >= d2) ? c1 : c2;
    txt(gC, cc[0], cc[1] + 4 * K, 'PF = ' + dist.toFixed(2),
        { fill: COL.segF, size: FS * 0.92, anchor: 'middle', weight: 'bold' });

    var sideD = (pxw >= h) ? 1 : -1;
    txt(gC, Dx + sideD * 11 * K, (Py + Dy) / 2 + 4 * K, 'PD = ' + dist.toFixed(2),
        { fill: COL.segD, size: FS * 0.92, anchor: (sideD > 0 ? 'start' : 'end'), weight: 'bold' });

    var bside = (pxw >= h) ? -1 : 1;
    var bx = vXs + bside * 15 * K, cap = 4 * K, bcol = '#555';
    [[vYs, fYs], [vYs, dYs]].forEach(function (pair) {
      gC.line(bx, pair[0], bx, pair[1]).stroke({ color: bcol, width: Math.max(0.7, 1.1 * K) });
      gC.line(bx - cap, pair[0], bx + cap, pair[0]).stroke({ color: bcol, width: Math.max(0.7, 1.1 * K) });
      gC.line(bx - cap, pair[1], bx + cap, pair[1]).stroke({ color: bcol, width: Math.max(0.7, 1.1 * K) });
      txt(gC, bx + bside * 6 * K, (pair[0] + pair[1]) / 2 + 4 * K, 'p',
          { fill: '#333', size: FS * 0.95, style: 'italic', anchor: (bside > 0 ? 'start' : 'end') });
    });

    gC.circle(15 * K).center(Px, Py).fill(COL.sym).opacity(0.28);
    gC.circle(8.5 * K).center(Px, Py).fill(COL.curve).stroke({ color: '#fff', width: Math.max(0.8, 1.6 * K) });
    var pl = (pxw >= h) ? 1 : -1;
    txt(gC, Px + pl * 11 * K, Py - 9 * K, 'P',
        { fill: COL.curve, size: FS * 1.05, weight: 'bold', anchor: (pl > 0 ? 'start' : 'end') });

    gC.css('cursor', 'pointer');
    gC.on('mousemove', function (e) {
      showTooltip('PF = PD = ' + dist.toFixed(2) + '  (both equal p = ' + p.toFixed(1) + ' at the vertex)', e);
    });
    gC.on('mouseleave', hideTooltip);
    gC.on('click', function () {
      showPopup('Equal distances',
        'The teal segment runs from P to the focus; the red segment drops perpendicular from P to the directrix. They measure ' +
        dist.toFixed(2) + ' each — and they stay equal for every position of P. At the vertex both shrink to p, which is why the vertex sits exactly halfway between focus and directrix.');
    });
  }

  applyHover();
}

/* ── interaction handlers ───────────────────────────────────────────────── */
function update_focalDistance(v) { figState.p = v; render(); }
function update_samplePoint(v) { figState.t = v; render(); }
function toggle_viewMode(on) { figState.construct = !!on; render(); }

/* ── demo steps ─────────────────────────────────────────────────────────── */
var DEMO = [
  { title: '1 · The named parts',
    narration: 'The standard labeled parabola: dark-blue curve, its vertex, the teal focus above it, the red directrix below, the orange axis of symmetry through both, and the dashed latus rectum across the focus. Hover any feature to light it up alone.',
    state: { viewMode: 'Labeled features', focalDistance: 1 } },
  { title: '2 · Why equidistant?',
    narration: 'Switch to the distance construction. A point P on the curve grows a teal segment to the focus and a red perpendicular segment down to the directrix — and they are exactly the same length.',
    state: { viewMode: 'Distance construction', focalDistance: 1, samplePoint: 1.6 } },
  { title: '3 · It holds everywhere',
    narration: 'Slide P along the curve. The two segments change length together but never differ — this equality is the definition of the parabola, not a special case.',
    state: { viewMode: 'Distance construction', focalDistance: 1, samplePoint: -2.4 } },
  { title: '4 · The vertex is the midpoint',
    narration: 'Move P to the bottom. Both distances shrink to the same value p: the vertex is the one point sitting halfway between focus and directrix, on the axis of symmetry.',
    state: { viewMode: 'Distance construction', focalDistance: 1, samplePoint: 0 } },
  { title: '5 · Changing p reshapes the curve',
    narration: 'Increase p: the focus climbs, the directrix drops the same amount, and the parabola opens out wide with a latus rectum of width 4p.',
    state: { viewMode: 'Distance construction', focalDistance: 2.5, samplePoint: 1.6 } },
  { title: '6 · A tight parabola',
    narration: 'Shrink p and the focus and directrix squeeze toward the vertex, pinching the curve into a narrow channel — same definition, different single parameter.',
    state: { viewMode: 'Labeled features', focalDistance: 0.4, samplePoint: 1.6 } }
];

function setSliderVal(id, v) {
  var inp = document.getElementById(id + 'Input');
  var out = document.getElementById(id + 'Val');
  if (inp) inp.value = v;
  if (out) out.value = v;
}

function applyStep(i) {
  figState.step = ((i % DEMO.length) + DEMO.length) % DEMO.length;
  var s = DEMO[figState.step], st = s.state || {};
  if (st.focalDistance != null) { setSliderVal('focalDistance', st.focalDistance); figState.p = st.focalDistance; }
  if (st.samplePoint != null) { setSliderVal('samplePoint', st.samplePoint); figState.t = st.samplePoint; }
  if (st.viewMode != null) {
    var on = (st.viewMode === 'Distance construction');
    var cb = document.getElementById('viewModeInput');
    if (cb) cb.checked = on;
    figState.construct = on;
  }
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (figState.step + 1) + ' / ' + DEMO.length;
  render();
}
function nextStep() { applyStep(figState.step + 1); }
function prevStep() { applyStep(figState.step - 1); }

/* ── resize + boot ──────────────────────────────────────────────────────── */
document.addEventListener('fig-resize', function () { render(); });

applyStep(0);
window.__markRendered();
